"use client";

import { useEffect, useRef, useState } from "react";

/**
 * Zählt eine Zahl hoch, sobald sie sichtbar wird.
 * Server-HTML enthält bereits den Endwert (SEO, kein Layout-Sprung).
 */
export default function CountUp({ value, decimals = 0, duration = 1600, prefix = "", suffix = "", className }) {
  const ref = useRef(null);
  const ziel = Number(value) || 0;
  const [anzeige, setAnzeige] = useState(ziel);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

    let raf;
    const io = new IntersectionObserver(
      ([e]) => {
        if (!e.isIntersecting) return;
        io.disconnect();
        const start = performance.now();
        const schritt = (t) => {
          const p = Math.min((t - start) / duration, 1);
          const eased = 1 - Math.pow(1 - p, 4);
          setAnzeige(ziel * eased);
          if (p < 1) raf = requestAnimationFrame(schritt);
        };
        setAnzeige(0);
        raf = requestAnimationFrame(schritt);
      },
      { threshold: 0.4 }
    );
    io.observe(el);
    return () => {
      io.disconnect();
      cancelAnimationFrame(raf);
    };
  }, [ziel, duration]);

  return (
    <span ref={ref} className={className ? `ov-num ${className}` : "ov-num"}>
      {prefix}
      {anzeige.toLocaleString("de-DE", { minimumFractionDigits: decimals, maximumFractionDigits: decimals })}
      {suffix}
    </span>
  );
}

  --radius-6xl: 3rem;

  --animate-ov-einblenden: ov-einblenden var(--ov-dauer-m, 240ms) var(--ease-ov-out) both;
  --animate-ov-auftauchen: ov-auftauchen var(--ov-dauer-l, 420ms) var(--ease-ov-out) both;
  --animate-ov-skalieren: ov-skalieren var(--ov-dauer-m, 240ms) var(--ease-ov-out) both;
  --animate-ov-ping: ov-ping 1.8s var(--ease-ov-out) infinite;
  --animate-ov-drehen: ov-drehen 0.8s linear infinite;
}

@keyframes ov-float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}
@keyframes ov-marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
@keyframes ov-pulse-dot {
  0% { box-shadow: 0 0 0 0 rgba(140, 186, 88, 0.7); }
  70% { box-shadow: 0 0 0 10px rgba(140, 186, 88, 0); }
  100% { box-shadow: 0 0 0 0 rgba(140, 186, 88, 0); }
}
@keyframes ov-shimmer {
  from { background-position: -200% 0; }
  to { background-position: 200% 0; }
}

:root {
  --background: #ffffff;
  --foreground: #171717;
  -webkit-tap-highlight-color: transparent;
}

/* Spürbares Drücken auf den Haupt-Handlungsaufrufen. `scale` statt
   `transform`, damit bestehende translate-Hover-Effekte erhalten bleiben. */
@media (prefers-reduced-motion: no-preference) {
  a[style*="669933"],
  button[style*="669933"] {
    transition-property: background-color, color, scale, box-shadow;
  }
  a[style*="669933"]:active,
  button[style*="669933"]:active {
    scale: 0.98;
  }
}

/* Dezente Scrollleiste im Markenton (dort, wo das System sie zeigt). */
html {
  scrollbar-color: #b9cda3 transparent;
}


/* ------------------------------------------------------------------
   BEWEGUNG REDUZIEREN
   114 Elemente animieren. Wer im Betriebssystem „Bewegung reduzieren"
   eingestellt hat, bekam das bisher trotzdem zu sehen.
   ------------------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

@media (prefers-reduced-motion: no-preference) {
  html {
    scroll-behavior: smooth;
  }
}

/* ------------------------------------------------------------------
   FORTSCHRITTSBALKEN DES HERO-SLIDERS
   Zeigt, wie lange der aktuelle Slide noch steht. Unter
.ov-noise::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.06;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
}

/* Glas-Karte für Inhalte auf Bildern / dunklen Flächen */
.ov-glass {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.14);
  backdrop-filter: blur(16px) saturate(140%);
  -webkit-backdrop-filter: blur(16px) saturate(140%);
}

/* Karten mit Licht-Kante beim Hover */
.ov-card-hover {
  transition: transform 350ms cubic-bezier(0.22, 1, 0.36, 1), box-shadow 350ms cubic-bezier(0.22, 1, 0.36, 1), border-color 350ms;
}
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  .ov-card-hover:hover {
    transform: translateY(-4px);
    box-shadow: 0 2px 6px -2px rgba(15, 23, 42, 0.06), 0 24px 48px -16px rgba(15, 23, 42, 0.18);
  }
}

/* Reveal-Animation (gesteuert von <Reveal/>). Ohne JS bleibt alles sichtbar. */
.ov-reveal {
  /* 2.0: nur transform/opacity (kein filter: blur – teuer beim Scrollen) */
  transition:
    opacity 700ms cubic-bezier(0.22, 1, 0.36, 1),
    transform 700ms cubic-bezier(0.22, 1, 0.36, 1);
  transition-delay: var(--ov-delay, 0ms);
}
.js-ready .ov-reveal:not(.is-visible) {
  opacity: 0;
  transform: translate3d(0, 24px, 0);
}
.js-ready .ov-reveal[data-dir="left"]:not(.is-visible) { transform: translate3d(-32px, 0, 0); }
.js-ready .ov-reveal[data-dir="right"]:not(.is-visible) { transform: translate3d(32px, 0, 0); }
.js-ready .ov-reveal[data-dir="scale"]:not(.is-visible) { transform: scale(0.96); }
@media (prefers-reduced-motion: reduce) {
  .js-ready .ov-reveal:not(.is-visible) { opacity: 1; transform: none; }
}

/* Schieberegler im Markenstil – für alle Rechner */
.ov-range {
  -webkit-appearance: none;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.07), 0 0 0 1px var(--ov-nacht-linie);
}
/* Marken-Verläufe für Hero-Kacheln und „Nächster Schritt“ */
.ov-verlauf-nacht {
  background:
    radial-gradient(120% 80% at 0% 0%, rgba(102, 153, 51, 0.22), transparent 55%),
    radial-gradient(90% 70% at 100% 100%, rgba(31, 90, 161, 0.35), transparent 60%),
    var(--ov-nacht-1);
}
.ov-verlauf-gruen {
  background:
    radial-gradient(100% 90% at 100% 0%, rgba(174, 208, 131, 0.35), transparent 55%),
    linear-gradient(135deg, var(--color-ov-600), var(--color-ov-800));
}
/* Haarlinie, die zu den Rändern ausläuft */
.ov-trenner {
  height: 1px;
  border: 0;
  background: linear-gradient(90deg, transparent, var(--color-ink-200) 15%, var(--color-ink-200) 85%, transparent);
}

/* ---------- Motion-Muster ---------- */

/* Hover-Lift: Bewegung per transform, Schatten über Pseudo-Element per
   opacity (kein box-shadow-Repaint). Nicht mit .ov-noise kombinieren. */
.ov-lift {
  position: relative;
  isolation: isolate;
  transition: transform var(--ov-dauer-s) var(--ov-ease-out);
}
.ov-lift::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  box-shadow: var(--ov-e4);
  opacity: 0;
  transition: opacity var(--ov-dauer-m) var(--ov-ease-out);
  pointer-events: none;
}
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  .ov-lift:hover { transform: translate3d(0, -3px, 0); }
}
@media (hover: hover) {
  .ov-lift:hover::before { opacity: 1; }
}
.ov-lift:focus-visible::before { opacity: 1; }

/* Press: kurzes Eindrücken bei allem Klickbaren */
.ov-press { transition: transform var(--ov-dauer-s) var(--ov-ease-out); }
@media (prefers-reduced-motion: no-preference) {
  .ov-press:active { transform: scale(0.975); transition-duration: 60ms; }
}

/* Stagger: Kinder erscheinen nacheinander, sobald der Elternblock sichtbar
